const cfg = $('⚙️ Configuration prospection').first().json;
let queries = [];
try { queries = JSON.parse(cfg.queries || '[]'); } catch (e) { queries = []; }

const products = Array.isArray($json.products) ? $json.products : [];
const catalog = products.map(p => ({
  title: String(p.title || '').trim(),
  handle: String(p.handle || '').trim(),
  type: String(p.product_type || '').trim(),
  price: String(p.variants?.[0]?.price || ''),
  url: cfg.storeUrl + '/products/' + String(p.handle || '').trim()
})).filter(p => p.title && p.handle);

if (!queries.length) throw new Error('Aucune requête de prospection configurée.');
if (!catalog.length) throw new Error('Catalogue Shopify public vide ou inaccessible.');

return queries.map(q => ({
  json: {
    query: String(q).trim(),
    location: cfg.location,
    maxPerQuery: Number(cfg.maxPerQuery || 8),
    minScore: Number(cfg.minScore || 70),
    maxDrafts: Number(cfg.maxDrafts || 10),
    aiModel: cfg.aiModel,
    storeUrl: cfg.storeUrl,
    dedupDays: Number(cfg.dedupDays || 90),
    catalog
  }
}));

const searches = $('🧭 Préparer recherches + catalogue').all();
const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const payload = inputs[i]?.json || {};

  if (payload.error) {
    throw new Error('SerpAPI: ' + String(payload.error));
  }

  const cfg = searches[i]?.json || searches[0]?.json || {};
  const places = Array.isArray(payload.local_results) ? payload.local_results : [];

  for (const p of places.slice(0, Number(cfg.maxPerQuery || 8))) {
    const nom = String(p.title || '').trim();
    if (!nom) continue;

    let website = String(p.website || p.links?.website || '').trim();
    const telephone = String(p.phone || '').trim();
    const adresse = String(p.address || '').trim();
    const rating = Number(p.rating || 0);
    const reviews = Number(p.reviews || 0);

    let domain = '';

    if (website) {
      if (!/^https?:\/\//i.test(website)) {
        website = 'https://' + website.replace(/^\/+/, '');
      }

      try {
        domain = new URL(website).hostname.replace(/^www\./, '').toLowerCase();
      } catch (e) {
        website = '';
        domain = '';
      }

      if (domain.includes('google.')) {
        website = '';
        domain = '';
      }
    }

    const stableId = String(
      p.place_id ||
      p.data_id ||
      p.data_cid ||
      domain ||
      (nom + '|' + adresse)
    ).trim();

    if (!stableId) continue;

    const key = stableId
      .toLowerCase()
      .replace(/\s+/g, ' ')
      .trim();

    out.push({
      json: {
        nom,
        categorie: String(cfg.query || ''),
        adresse,
        telephone,
        website,
        domain,
        rating,
        reviews,
        placeId:String(p.place_id || ''),
        dataId:String(p.data_id || ''),
        googleMapsUrl: String(
          p.place_id
            ? `https://www.google.com/maps/search/?api=1&query_place_id=${p.place_id}`
            : ''
        ),
        prospectKey: key,
        dateRecherche: new Date().toISOString()
      },
      pairedItem: { item: i }
    });
  }
}

return out;

const cfg = $('⚙️ Configuration prospection').first().json;
const maxAgeMs = Number(cfg.dedupDays || 90) * 86400000;
const now = Date.now();
const data = $getWorkflowStaticData('global');
data.preparedProspects = data.preparedProspects || {};
for (const [k,ts] of Object.entries(data.preparedProspects)) {
  if (!ts || now - Number(ts) > maxAgeMs) delete data.preparedProspects[k];
}
const seenRun = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const key = String(j.prospectKey || '').trim();
  if (!key || seenRun.has(key) || data.preparedProspects[key]) continue;
  seenRun.add(key);
  if (!/^https?:\/\//i.test(String(j.website||''))) continue;
  out.push({json:j});
}
return out;

const leads = $('🛡️ Dédupliquer + avec site').all();
const blockedDomains = ['example.com','sentry.io','wixpress.com','cloudflare.com','schema.org','wordpress.org','google.com','googleusercontent.com'];
const blockedLocal = /^(noreply|no-reply|donotreply|mailer-daemon|privacy|abuse|webmaster)$/i;
const out = [];
for (let i = 0; i < $input.all().length; i++) {
  const lead = leads[i]?.json || {};
  const raw = JSON.stringify($input.all()[i]?.json ?? '').replace(/\\u003c/g,'<').replace(/&commat;/gi,'@');
  const matches = [...raw.matchAll(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi)]
    .map(m => m[0].toLowerCase().replace(/["'<>),;\\]+$/g,''));
  const unique=[...new Set(matches)].filter(e=>{
    const [local,domain='']=e.split('@');
    if(!local||!domain||blockedLocal.test(local)) return false;
    if(blockedDomains.some(d=>domain===d||domain.endsWith('.'+d))) return false;
    if(/\.(png|jpg|jpeg|gif|svg|webp)$/i.test(e)) return false;
    return true;
  });
  const sameDomain=unique.find(e=>lead.domain && (e.endsWith('@'+lead.domain)||e.split('@')[1]?.endsWith('.'+lead.domain)));
  const generic=unique.find(e=>/^(contact|info|hello|bonjour|office|admin|sales|commercial|reservation|booking)@/i.test(e));
  const email=sameDomain||generic||unique[0]||'';
  if (!email) continue;
  out.push({json:{...lead,email,sourceEmail:'site web public'}});
}
return out;

