const leads = $('🧹 Normaliser prospects').all();
const inputs = $input.all();
const out = [];

for (let i = 0; i < inputs.length; i++) {
  const lead = leads[i]?.json || {};
  const payload = inputs[i]?.json || {};
  const place = payload.place_results || {};

  let website = String(lead.website || place.website || place.links?.website || '').trim();
  let domain = String(lead.domain || '').trim();

  if (website) {
    if (!/^https?:\/\//i.test(website)) {
      website = 'https://' + website.replace(/^\/+/, '');
    }
    try {
      domain = new URL(website).hostname.replace(/^www\./, '').toLowerCase();
    } catch (e) {
      website = '';
      domain = '';
    }
    if (domain.includes('google.')) {
      website = '';
      domain = '';
    }
  }

  out.push({
    json:{
      ...lead,
      website,
      domain,
      telephone:String(lead.telephone || place.phone || '').trim(),
      adresse:String(lead.adresse || place.address || '').trim(),
      rating:Number(lead.rating || place.rating || 0),
      reviews:Number(lead.reviews || place.reviews || 0)
    },
    pairedItem:{item:i}
  });
}

return out;
